561:     var short, desc, optional, line, seen_opts = [],
562:         switch_pad = cli.option_width;
563: 
564:     var trunc_desc = function (pref, desc, len) {
565:         var pref_len = pref.length,
566:             desc_len = cli.width - pref_len,
567:             truncated = '';
568:         if (desc.length <= desc_len) {
569:             return desc;
570:         }
571:         var desc_words = (desc+'').split(' '), chars = 0, word;
572:         while (desc_words.length) {
573:             truncated += (word = desc_words.shift()) + ' ';
574:             chars += word.length;
575:             if (desc_words.length && chars + desc_words[0].length > desc_len) {
576:                 truncated += '\n' + pad(pref_len);
577:                 chars = 0;
578:             }
579:         }
580:         return truncated;
581:     };
582: 
583:     usage = usage || cli.app + ' [OPTIONS]' + (command_list.length ? ' <command>' : '') + ' [ARGS]';
584:     if (cli.no_color) {
585:         console.error('Usage:\n  ' + usage);
586:         console.error('Options: ');
587:     } else {
588:         console.error('\x1b[1mUsage\x1b[0m:\n  ' + usage);
589:         console.error('\n\x1b[1mOptions\x1b[0m: ');
590:     }
591:     for (var opt in opt_list) {
592: 
593:         if (opt.length === 1) {
594:             long = opt_list[opt][0];
595:             short = opt;
596:         } else {
597:             long = opt;
598:             short = opt_list[opt][0];
599:         }
600: 
601:         //Parse opt_list
602:         desc = opt_list[opt][1].trim();
603:         type = opt_list[opt].length >= 3 ? opt_list[opt][2] : null;
604:         optional = opt_list[opt].length === 4 ? opt_list[opt][3] : null;
605: 
606:         //Build usage line
607:         if (short === long) {
608:             if (short.length === 1) {
609:                 line = '  -' + short;
610:             } else {
611:                 line = '      --' + long;
612:             }
613:         } else if (short) {
614:             line = '  -' + short + ', --' + long;
615:         } else {
616:             line = '      --' + long;
617:         }
618:         line += ' ';
619: 
620:         if (type) {
621:             if (type instanceof Array) {
622:                 desc += '. VALUE must be either [' + type.join('|') + ']';
623:                 type = 'VALUE';
624:             }
625:             if (type === true || type === 1) {
626:                 type = long.toUpperCase();
627:             }
628:             type = type.toUpperCase();
629:             if (type === 'FLOAT' || type === 'INT') {
630:                 type = 'NUMBER';
631:             }
632:             line += optional ? '[' + type + ']' : type;
633:         }
634:         line = pad(line, switch_pad);
635:         line += trunc_desc(line, desc);
636:         line += optional ? ' (Default is ' + optional + ')' : '';
637:         console.error(line.replace('%s', '%\0s'));
638: 
639:         seen_opts.push(short);
640:         seen_opts.push(long);
641:     }
642:     if (enable.timeout && seen_opts.indexOf('t') === -1 && seen_opts.indexOf('timeout') === -1) {
643:         console.error(pad('  -t, --timeout N', switch_pad) + 'Exit if the process takes longer than N seconds');
644:     }
645:     if (enable.status) {
646:         if (seen_opts.indexOf('k') === -1 && seen_opts.indexOf('no-color') === -1) {
647:             console.error(pad('  -k, --no-color', switch_pad) + 'Omit color from output');
648:         }
649:         if (seen_opts.indexOf('debug') === -1) {
650:             console.error(pad('      --debug', switch_pad) + 'Show debug information');
651:         }
652:     }
653:     if (enable.catchall && seen_opts.indexOf('c') === -1 && seen_opts.indexOf('catch') === -1) {
654:         console.error(pad('  -c, --catch', switch_pad) + 'Catch unanticipated errors');
655:     }
656:     if (enable.version && seen_opts.indexOf('v') === -1 && seen_opts.indexOf('version') === -1) {
657:         console.error(pad('  -v, --version', switch_pad) + 'Display the current version');
658:     }
659:     if (enable.help && seen_opts.indexOf('h') === -1 && seen_opts.indexOf('help') === -1) {
660:         console.error(pad('  -h, --help', switch_pad) + 'Display help and usage details');
661:     }
662:     if (command_list.length) {
663:         console.error('\n\x1b[1mCommands\x1b[0m: ');
664:         if (!Array.isArray(commands)) {
665:             for (var c in commands) {
666:                 line = '  ' + pad(c, switch_pad - 2);
667:                 line += trunc_desc(line, commands[c]);
