874:     if (typeof encoding === 'function') {
875:         callback = encoding;
876:         encoding = 'utf8';
877:     } else if (typeof file === 'function') {
878:         callback = file;
879:         encoding = 'utf8';
880:         file = 'stdin';
881:     }
882:     if (file === 'stdin') {
883:         file = process.openStdin();
884:     } else {
