971:     var defaultStackErrorHandler = function (req, res, err) {
972:         if (err) {
973:             console.error(err.stack);
974:             res.writeHead(500, {"Content-Type": "text/plain"});
975:             return res.end(err.stack + "\n");
976:         }
977:         res.writeHead(404, {"Content-Type": "text/plain"});
978:         res.end("Not Found\n");
979:     };
980:     var handle, error;
981:     handle = error = defaultStackErrorHandler;
982:     var layers = Array.prototype.slice.call(arguments);
983: 
984:     //Allow createServer(a,b,c) and createServer([a,b,c])
985:     if (layers.length && layers[0] instanceof Array) {
986:         layers = layers[0];
987:     }
988:     layers.reverse().forEach(function (layer) {
989:         var child = handle;
990:         handle = function (req, res) {
991:             try {
992:                 layer(req, res, function (err) {
993:                     if (err) return error(req, res, err);
994:                     child(req, res);
995:                 });
996:             } catch (err) {
997:                 error(req, res, err);
998:             }
999:         };
